//! Co-op fork (M27): every environment switch the game reads is listed in
//! `docs/coop/plan/switches.md`, generated by `tools/coop/switches.py --write`. This test is the
//! list's guard: a `SKATE2_*` name read anywhere in `crates/` or `apps/` that the page does not
//! list, or a listed name nothing reads any more, fails it.

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;
    use std::path::{Path, PathBuf};

    fn root() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
    }

    /// The `SKATE2_*` names in string literals of one source text.
    fn literals(text: &str, into: &mut BTreeSet<String>) {
        for (start, _) in text.match_indices("\"SKATE2_") {
            let name: String = text[start + 1..].chars().take_while(|c| c.is_ascii_uppercase() || c.is_ascii_digit() || *c == '_').collect();
            if name.len() > "SKATE2_".len() && text[start + 1 + name.len()..].starts_with('"') {
                into.insert(name);
            }
        }
    }

    fn read(folder: &Path, into: &mut BTreeSet<String>) {
        let Ok(entries) = std::fs::read_dir(folder) else { return };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                if !matches!(path.file_name().and_then(|name| name.to_str()), Some("target" | "fixtures")) {
                    read(&path, into);
                }
            } else if path.extension().is_some_and(|extension| extension == "rs")
                && let Ok(text) = std::fs::read_to_string(&path)
            {
                literals(&text, into);
            }
        }
    }

    #[test]
    fn every_switch_the_code_reads_is_listed_and_every_listed_one_is_read() {
        let mut read_names = BTreeSet::new();
        for base in ["crates", "apps"] {
            read(&root().join(base), &mut read_names);
        }
        let page = std::fs::read_to_string(root().join("docs/coop/plan/switches.md")).expect("docs/coop/plan/switches.md");
        let listed: BTreeSet<String> = page
            .lines()
            .filter_map(|line| line.strip_prefix("| `")?.split('`').next().filter(|name| name.starts_with("SKATE2_")).map(str::to_owned))
            .collect();
        let unlisted: Vec<&String> = read_names.difference(&listed).collect();
        let stale: Vec<&String> = listed.difference(&read_names).collect();
        assert!(unlisted.is_empty() && stale.is_empty(), "run tools/coop/switches.py --write: unlisted {unlisted:?}, listed but never read {stale:?}");
    }
}
